// CreateTable creates the Purchase_Line table for the specified company (SQLite)
// The db parameter can be either *sql.DB or *sql.Tx
func (t *PurchaseLine) CreateTable(db database.Executor, company string) error {
	return t.CreateTableWithDBType(db, company, database.DBTypeSQLite)
}

// CreateTableWithDBType creates the Purchase_Line table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *PurchaseLine) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, PurchaseLineTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetPurchaseLinePostgresTableSchema()
	} else {
		schema = GetPurchaseLineTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Purchase_Line table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *PurchaseLine) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, PurchaseLineTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_type, document_no, line_no)`,
		fmt.Sprintf("%s$Purchase_Line$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (type, no)`,
		fmt.Sprintf("%s$Purchase_Line$type_no", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index type_no: %w", err)
	}
	var keys []sift.Key
	for _, spec := range purchaseLineSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, PurchaseLineTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, PurchaseLineTableName, keys)
}

// purchaseLineSIFTSpecs are the table's keys with sum_index_fields
func purchaseLineSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *PurchaseLine) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, PurchaseLineTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range purchaseLineSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, PurchaseLineTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: PurchaseLineTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, PurchaseLineTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

